-- Modelo vigente, crear solo en una BBDD nueva autorizada.
CREATE TABLE `configuracion_bbdd` (
  `_idconfiguracionbbdd` INT UNSIGNED NOT NULL AUTO_INCREMENT COMMENT 'PK interna estable de la configuración de BBDD externa. El renombre conserva sus valores y las referencias de los consumidores; nunca se recibe desde la interfaz.',
  `configuracionbbddid` VARCHAR(50) NOT NULL DEFAULT (uuid()) COMMENT 'UUID público estable de la configuración externa. Se conserva durante el renombre y forma parte del contexto autenticado del secreto existente.',
  `code` VARCHAR(20) NOT NULL COMMENT 'Código único y legible de presentación de esta configuración, generado por el servicio. No sustituye la PK interna ni el UUID público y no identifica ninguna operación de negocio.',
  `alias` VARCHAR(200) NOT NULL COMMENT 'Nombre de presentación de la configuración para administradores autorizados. No participa en la autenticación ni en la construcción de consultas; los consumidores muestran este alias sin recibir las credenciales.',
  `motor` VARCHAR(10) CHARACTER SET ascii COLLATE ascii_bin NOT NULL DEFAULT 'MYSQL' COMMENT 'Motor de la BBDD externa. Esta versión soporta MYSQL y MARIADB mediante un adaptador compatible; otros motores requieren implementar su adaptador y validación antes de habilitarlos.',
  `host` VARCHAR(253) NOT NULL COMMENT 'Nombre DNS o dirección del servidor externo, sin protocolo, puerto ni credenciales. Guardar no consulta la red; probar o utilizar exige política de destinos autorizados y verificación de identidad TLS.',
  `puerto` SMALLINT UNSIGNED NOT NULL DEFAULT 3306 COMMENT 'Puerto TCP del MySQL entre 1 y 65535, sujeto a lista de destinos y puertos autorizados. No habilita explorar otros servicios de red.',
  `base_datos` VARCHAR(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin NOT NULL COMMENT 'Nombre de la base externa seleccionada o escrito manualmente por el administrador. La lista obtenida durante la prueba es orientativa; no se exige una prueba exitosa para guardar este valor.',
  `usuario` VARCHAR(128) NOT NULL COMMENT 'Nombre de usuario de autenticación de la BBDD externa. Sus permisos son administrados en el servidor remoto. Cada consumidor aplica sus propias restricciones; la sincronización bancaria exige exclusivamente SELECT y USAGE.',
  `password_cifrado` VARBINARY(2048) NOT NULL COMMENT 'Bytes de la contraseña cifrada con AES-256-GCM, sin Base64 ni tag concatenado. Nunca se devuelve al frontend, se registra en logs ni se copia al historial. La interfaz permite reemplazarla, no recuperarla.',
  `password_nonce` BINARY(12) NOT NULL COMMENT 'Nonce criptográficamente aleatorio de 96 bits por cifrado. Debe ser único bajo la misma clave, incluidas rotaciones; no se deriva de la hora, el UUID ni la contraseña.',
  `password_tag` BINARY(16) NOT NULL COMMENT 'Etiqueta de autenticación GCM de 128 bits. Debe verificarse antes de usar la contraseña; ante fallo se rechaza el secreto sin recurrir a otro modo de descifrado.',
  `clave_version` VARCHAR(50) CHARACTER SET ascii COLLATE ascii_bin NOT NULL COMMENT 'Identificador de la clave externa AES de 256 bits. No contiene material de clave. Se resuelve con BBDD_KEYS fuera de esta base; se conservan versiones anteriores para descifrar conexiones existentes.',
  `cifrado_version` SMALLINT UNSIGNED NOT NULL DEFAULT 1 COMMENT 'Formato V1: AES-256-GCM, nonce de 12 bytes, tag de 16 y AAD canónico ligado al UUID de conexión, campo password y versión de clave. Cambiar el formato requiere una migración explícita.',
  `tls_ca_referencia` VARCHAR(255) NULL COMMENT 'Referencia autorizada a una CA instalada por infraestructura; NULL usa las autoridades del sistema. No admite rutas libres ni claves privadas. Verificar certificado y nombre del servidor es siempre obligatorio.',
  `habilitado` TINYINT NOT NULL DEFAULT 0 COMMENT 'Disponibilidad administrativa: 1 habilitado y 0 deshabilitado para los consumidores. Puede guardarse sin probar la conexión; no acredita conectividad ni permisos. Deshabilitar conserva credenciales, referencias e historial.',
  `version` INT UNSIGNED NOT NULL DEFAULT 1 COMMENT 'Versión incremental para concurrencia optimista. Toda modificación desde la interfaz exige la versión vigente y la incrementa; no representa una prueba exitosa ni la versión del servidor externo.',
  `idusuariocrea` INT NOT NULL COMMENT 'Usuario autenticado o cuenta técnica habilitada responsable del alta. Se asigna explícitamente en el servicio; no se acepta del frontend ni se atribuye automáticamente al usuario 1.',
  `fechacrea` TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3) COMMENT 'Instante UTC de creación de la configuración con precisión de milisegundos. Es metadato administrativo local y no representa fechas de los datos externos ni el tiempo de una prueba de conexión.',
  `idusuariomod` INT NOT NULL COMMENT 'Usuario autenticado responsable de la última modificación administrativa. Lo asigna el servicio desde la sesión junto con la versión y fecha de cambio; no se acepta del formulario.',
  `fechamod` TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3) COMMENT 'Instante UTC de la última modificación administrativa, actualizado explícitamente por el servicio con precisión de milisegundos. No tiene ON UPDATE y no almacena tiempos de diagnóstico ni funciona como cursor remoto.',
  `estado` TINYINT NOT NULL DEFAULT 1 COMMENT 'Vigencia lógica del proyecto: 1 ACTIVO y 2 ELIMINADO. No implica borrado físico ni acredita conectividad. Habilitado controla la disponibilidad para consumidores de forma independiente; se preservan credenciales y referencias.',
  `tls_habilitado` TINYINT NOT NULL DEFAULT 1 COMMENT 'Decisión explícita de transporte por configuración: 1 exige TLS con certificado e identidad verificados; 0 permite conexión sin TLS con advertencia visible de que contraseña y datos pueden viajar sin cifrar. Por defecto todas las configuraciones existentes y nuevas requieren TLS. No altera AES-GCM de la contraseña almacenada ni autoriza reintentos automáticos sin cifrado.',
  PRIMARY KEY (`_idconfiguracionbbdd`),
  UNIQUE KEY `UQ_ftbc_uuid` (`configuracionbbddid`),
  UNIQUE KEY `UQ_ftbc_code` (`code`),
  UNIQUE KEY `UQ_ftbc_nonce` (`clave_version`, `password_nonce`),
  CONSTRAINT `CK_cbbdd_tls` CHECK (`tls_habilitado` IN (0,1)),
  CONSTRAINT `CK_ftbc_motor` CHECK (`motor` IN ('MYSQL', 'MARIADB')),
  CONSTRAINT `CK_ftbc_puerto` CHECK (`puerto` BETWEEN 1 AND 65535),
  CONSTRAINT `CK_ftbc_crypto` CHECK (`cifrado_version` = 1 AND OCTET_LENGTH(`password_cifrado`) > 0),
  CONSTRAINT `CK_ftbc_habilitado` CHECK (`habilitado` IN (0, 1)),
  CONSTRAINT `CK_ftbc_version` CHECK (`version` > 0),
  CONSTRAINT `CK_ftbc_estado` CHECK (`estado` IN (1, 2))
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci ROW_FORMAT=DYNAMIC COMMENT='Configuración reutilizable de acceso a BBDD externas, independiente de tablas de origen, transacciones y procesos de negocio. Credenciales AES-256-GCM con claves externas, TLS verificado y control administrativo de disponibilidad. Guardar no realiza conexiones remotas. Los diagnósticos y sus tiempos solo viven en la respuesta de prueba y nunca se almacenan.';
CREATE TABLE `factor_transaccion_bancaria_fuente` (
  `_idconfiguracionbbdd` INT UNSIGNED NOT NULL COMMENT 'PK y FK de la configuración externa usada por el consumidor bancario. Conserva el identificador existente durante el desacoplamiento; una configuración genérica puede existir sin fuente bancaria.',
  `tabla_origen` VARCHAR(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin NOT NULL DEFAULT 'bcp_transaccion_ahorro' COMMENT 'Tabla o vista de origen del contrato bancario. Pertenece exclusivamente al consumidor de transacciones y no a las credenciales reutilizables. Solo admite identificadores simples y lecturas SELECT verificadas por el adaptador bancario.',
  PRIMARY KEY (`_idconfiguracionbbdd`),
  CONSTRAINT `FK_ftbf_configuracion` FOREIGN KEY (`_idconfiguracionbbdd`) REFERENCES `configuracion_bbdd` (`_idconfiguracionbbdd`) ON DELETE RESTRICT ON UPDATE RESTRICT
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='Contrato de origen del consumidor bancario separado de la configuración genérica de BBDD. Conserva la tabla de todas las conexiones anteriores, incluidas las que aún no tienen cuentas mapeadas. No contiene credenciales ni resultados de pruebas.';
CREATE TABLE `factor_transaccion_bancaria_origen_cuenta` (
  `_idfactortransaccionbancariaorigencuenta` INT UNSIGNED NOT NULL AUTO_INCREMENT COMMENT 'PK interna autoincremental. Identifica este registro para relaciones internas; no se acepta desde la interfaz ni representa el identificador de una operación bancaria.',
  `factortransaccionbancariaorigencuentaid` VARCHAR(50) NOT NULL DEFAULT (uuid()) COMMENT 'UUID público único y estable según el estándar del proyecto. Se utiliza en API y permanece tras correcciones, cambios de presentación y eliminación lógica.',
  `code` VARCHAR(20) NOT NULL COMMENT 'Código único de presentación generado por el servicio según el estándar del proyecto. No sustituye al UUID ni al número de operación del banco.',
  `_idconexion` INT UNSIGNED NOT NULL COMMENT 'Conexión MySQL a la que pertenece la etiqueta de cuenta. Una misma etiqueta puede existir en conexiones distintas; el servicio comprueba que la conexión esté habilitada.',
  `cuenta_origen` VARCHAR(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin NOT NULL COMMENT 'Cuenta o alias remoto normalizado como texto. V1 elimina CR/LF y espacios externos, conservando ceros iniciales y caracteres internos; no transforma el valor en número.',
  `_idfactorcuentabancaria` INT UNSIGNED NOT NULL COMMENT 'Cuenta bancaria del factor asignada explícitamente. El servicio valida titularidad, moneda y vigencia; nunca resuelve el mapeo solamente por últimos cuatro dígitos.',
  `habilitado` TINYINT NOT NULL DEFAULT 1 COMMENT '1 permite usar el mapeo y 0 lo suspende. Las transacciones históricas mantienen su referencia aunque se suspenda; no se borran ni se reasignan.',
  `version` INT UNSIGNED NOT NULL DEFAULT 1 COMMENT 'Versión incremental de concurrencia. Cambiar conexión o cuenta en un mapeo ya utilizado requiere un procedimiento revisado; no se altera la identidad histórica desde el CRUD ordinario.',
  `idusuariocrea` INT NOT NULL COMMENT 'Usuario autenticado o cuenta técnica habilitada responsable del alta. Se asigna explícitamente en el servicio; no se acepta del frontend ni se atribuye automáticamente al usuario 1.',
  `fechacrea` TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3) COMMENT 'Instante de creación con milisegundos y sesión de base de datos en UTC. No representa la fecha civil bancaria ni debe desplazarla al visualizar el movimiento en Lima.',
  `idusuariomod` INT NOT NULL COMMENT 'Usuario de la última modificación autorizada, obtenido de la sesión o cuenta técnica por el servicio. Se actualiza junto con el cambio y su evento histórico.',
  `fechamod` TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3) COMMENT 'Instante UTC de última modificación, actualizado explícitamente por el servicio. No tiene ON UPDATE ni se utiliza como cursor de modificaciones del MySQL remoto.',
  `estado` TINYINT NOT NULL DEFAULT 1 COMMENT 'Vigencia lógica del proyecto: 1=ACTIVO y 2=ELIMINADO. No implica borrado físico, ausencia del origen, éxito de sincronización ni conciliación con pagos.',
  PRIMARY KEY (`_idfactortransaccionbancariaorigencuenta`),
  UNIQUE KEY `UQ_ftboc_uuid` (`factortransaccionbancariaorigencuentaid`),
  UNIQUE KEY `UQ_ftboc_code` (`code`),
  UNIQUE KEY `UQ_ftboc_conexion_cuenta` (`_idconexion`, `cuenta_origen`),
  KEY `IX_ftboc_factorcuenta` (`_idfactorcuentabancaria`),
  CONSTRAINT `FK_ftboc_conexion` FOREIGN KEY (`_idconexion`) REFERENCES `configuracion_bbdd` (`_idconfiguracionbbdd`) ON DELETE RESTRICT ON UPDATE RESTRICT,
  CONSTRAINT `FK_ftboc_factorcuenta` FOREIGN KEY (`_idfactorcuentabancaria`) REFERENCES `factor_cuenta_bancaria` (`_idfactorcuentabancaria`) ON DELETE RESTRICT ON UPDATE RESTRICT,
  CONSTRAINT `CK_ftboc_cuenta` CHECK (CHAR_LENGTH(TRIM(`cuenta_origen`)) > 0),
  CONSTRAINT `CK_ftboc_habilitado` CHECK (`habilitado` IN (0, 1)),
  CONSTRAINT `CK_ftboc_version` CHECK (`version` > 0),
  CONSTRAINT `CK_ftboc_estado` CHECK (`estado` IN (1, 2))
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci ROW_FORMAT=DYNAMIC COMMENT='Mapeo explícito de una cuenta o alias del MySQL a la cuenta bancaria real del factor. Admite varios alias para una cuenta local, sin deducir titularidad por últimos dígitos. Un mapeo utilizado por movimientos no se reasigna silenciosamente a otra cuenta.';

CREATE TABLE `factor_transaccion_bancaria_sincronizacion` (
  `_idfactortransaccionbancariasincronizacion` INT UNSIGNED NOT NULL AUTO_INCREMENT COMMENT 'PK interna autoincremental. Identifica este registro para relaciones internas; no se acepta desde la interfaz ni representa el identificador de una operación bancaria.',
  `factortransaccionbancariasincronizacionid` VARCHAR(50) NOT NULL DEFAULT (uuid()) COMMENT 'UUID público único y estable según el estándar del proyecto. Se utiliza en API y permanece tras correcciones, cambios de presentación y eliminación lógica.',
  `code` VARCHAR(20) NOT NULL COMMENT 'Código único de presentación generado por el servicio según el estándar del proyecto. No sustituye al UUID ni al número de operación del banco.',
  `_idconexion` INT UNSIGNED NOT NULL COMMENT 'Conexión usada por la ejecución. Las cuentas incluidas deben pertenecer a sus mapeos habilitados; no se acepta una URL libre del cliente.',
  `disparador` VARCHAR(20) CHARACTER SET ascii COLLATE ascii_bin NOT NULL COMMENT 'PROGRAMADA, MANUAL o CARGA_LEGADO. Solo CARGA_LEGADO incorpora enriquecimientos históricos bajo autorización separada; los reintentos conservan la idempotencia.',
  `resultado` VARCHAR(20) CHARACTER SET ascii COLLATE ascii_bin NOT NULL DEFAULT 'EN_CURSO' COMMENT 'EN_CURSO, EXITOSA, PARCIAL, FALLIDA o INTERRUMPIDA. EXITOSA exige lectura completa y ausencia de incidencias de esa ejecución; PARCIAL puede haber confirmado lotes válidos.',
  `fecha_desde` DATE NULL COMMENT 'Primer día bancario incluido, sin hora ni conversión de zona. NULL junto con fecha_hasta significa todo el histórico autorizado de las cuentas declaradas.',
  `fecha_hasta` DATE NULL COMMENT 'Último día bancario incluido, de forma inclusiva. Debe ser igual o posterior a fecha_desde; ambos límites son nulos o ambos se informan.',
  `cuentas_alcance` JSON NOT NULL COMMENT 'Array no vacío de UUID públicos de los mapeos incluidos al iniciar la ejecución. Congela el alcance, no contiene secretos y el servicio valida pertenencia a la conexión.',
  `inicio` TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3) COMMENT 'Inicio UTC con milisegundos tras obtener bloqueo por conexión. El proceso no mantiene transacciones locales abiertas mientras espera respuesta de la red remota.',
  `fin` TIMESTAMP(3) NULL COMMENT 'Finalización UTC, también en fallos e interrupciones recuperadas. NULL mientras EN_CURSO; marcar una ejecución abandonada exige comprobar que su trabajador ya no está activo.',
  `lectura_completa` TINYINT NOT NULL DEFAULT 0 COMMENT '1 solo cuando se leyó de forma consistente todo el alcance. La ausencia de una fila no autoriza borrarla ni anularla localmente, incluso tras una lectura completa.',
  `filas_leidas` INT UNSIGNED NOT NULL DEFAULT 0 COMMENT 'Filas remotas efectivamente leídas. Es una métrica de procesamiento, no un saldo ni la cantidad de nuevos movimientos locales.',
  `filas_insertadas` INT UNSIGNED NOT NULL DEFAULT 0 COMMENT 'Movimientos nuevos confirmados en lotes cortos e idempotentes. Excluye filas existentes y no acumula importes monetarios.',
  `filas_existentes` INT UNSIGNED NOT NULL DEFAULT 0 COMMENT 'Observaciones compatibles con identidades ya registradas, incluidas altas manuales luego reconocidas. No habilita sobrescribir el enriquecimiento local.',
  `filas_incidencia` INT UNSIGNED NOT NULL DEFAULT 0 COMMENT 'Filas con validaciones fallidas, identidad ambigua o diferencias pendientes. No se ocultan convirtiéndolas en actualizaciones o inserciones automáticas.',
  `error_codigo` VARCHAR(50) NULL COMMENT 'Código técnico seguro definido por la aplicación. No se copia el mensaje original del driver, que podría revelar SQL, credenciales o datos de clientes.',
  `error_resumen` VARCHAR(500) NULL COMMENT 'Resumen sanitizado para usuarios autorizados. Excluye filas bancarias completas, secretos, materiales criptográficos y cadenas de conexión.',
  `idusuariocrea` INT NOT NULL COMMENT 'Usuario autenticado o cuenta técnica habilitada responsable del alta. Se asigna explícitamente en el servicio; no se acepta del frontend ni se atribuye automáticamente al usuario 1.',
  `fechacrea` TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3) COMMENT 'Instante de creación con milisegundos y sesión de base de datos en UTC. No representa la fecha civil bancaria ni debe desplazarla al visualizar el movimiento en Lima.',
  `idusuariomod` INT NOT NULL COMMENT 'Usuario de la última modificación autorizada, obtenido de la sesión o cuenta técnica por el servicio. Se actualiza junto con el cambio y su evento histórico.',
  `fechamod` TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3) COMMENT 'Instante UTC de última modificación, actualizado explícitamente por el servicio. No tiene ON UPDATE ni se utiliza como cursor de modificaciones del MySQL remoto.',
  `estado` TINYINT NOT NULL DEFAULT 1 COMMENT 'Vigencia lógica del proyecto: 1=ACTIVO y 2=ELIMINADO. No implica borrado físico, ausencia del origen, éxito de sincronización ni conciliación con pagos.',
  PRIMARY KEY (`_idfactortransaccionbancariasincronizacion`),
  UNIQUE KEY `UQ_ftbs_uuid` (`factortransaccionbancariasincronizacionid`),
  UNIQUE KEY `UQ_ftbs_code` (`code`),
  KEY `IX_ftbs_conexion_inicio` (`_idconexion`, `inicio`),
  CONSTRAINT `FK_ftbs_conexion` FOREIGN KEY (`_idconexion`) REFERENCES `configuracion_bbdd` (`_idconfiguracionbbdd`) ON DELETE RESTRICT ON UPDATE RESTRICT,
  CONSTRAINT `CK_ftbs_disparador` CHECK (`disparador` IN ('PROGRAMADA', 'MANUAL', 'CARGA_LEGADO')),
  CONSTRAINT `CK_ftbs_resultado` CHECK (`resultado` IN ('EN_CURSO', 'EXITOSA', 'PARCIAL', 'FALLIDA', 'INTERRUMPIDA')),
  CONSTRAINT `CK_ftbs_periodo` CHECK ((`fecha_desde` IS NULL AND `fecha_hasta` IS NULL) OR (`fecha_desde` IS NOT NULL AND `fecha_hasta` IS NOT NULL AND `fecha_hasta` >= `fecha_desde`)),
  CONSTRAINT `CK_ftbs_fin` CHECK ((`resultado` = 'EN_CURSO' AND `fin` IS NULL) OR (`resultado` <> 'EN_CURSO' AND `fin` IS NOT NULL AND `fin` >= `inicio`)),
  CONSTRAINT `CK_ftbs_completa` CHECK (`lectura_completa` IN (0, 1)),
  CONSTRAINT `CK_ftbs_exitosa` CHECK (`resultado` <> 'EXITOSA' OR (`lectura_completa` = 1 AND `filas_incidencia` = 0 AND `error_codigo` IS NULL)),
  CONSTRAINT `CK_ftbs_cuentas` CHECK (JSON_TYPE(`cuentas_alcance`) = 'ARRAY' AND JSON_LENGTH(`cuentas_alcance`) > 0),
  CONSTRAINT `CK_ftbs_estado` CHECK (`estado` IN (1, 2))
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci ROW_FORMAT=DYNAMIC COMMENT='Registro operativo de extracción MySQL: carga histórica, ejecución programada y reintento manual. Conserva alcance y resultados, sin credenciales ni filas de clientes en mensajes técnicos. No es un cursor confiable del origen ni configura cron.';

CREATE TABLE `factor_transaccion_bancaria` (
  `_idfactortransaccionbancaria` INT UNSIGNED NOT NULL AUTO_INCREMENT COMMENT 'PK interna autoincremental. Identifica este registro para relaciones internas; no se acepta desde la interfaz ni representa el identificador de una operación bancaria.',
  `factortransaccionbancariaid` VARCHAR(50) NOT NULL DEFAULT (uuid()) COMMENT 'UUID público único y estable según el estándar del proyecto. Se utiliza en API y permanece tras correcciones, cambios de presentación y eliminación lógica.',
  `code` VARCHAR(20) NOT NULL COMMENT 'Código único de presentación generado por el servicio según el estándar del proyecto. No sustituye al UUID ni al número de operación del banco.',
  `_idfactorcuentabancaria` INT UNSIGNED NOT NULL COMMENT 'Cuenta del factor del movimiento; debe coincidir con el mapeo remoto cuando exista. Permanece estable después del alta: una asignación errónea requiere resolución auditada conservando la identidad inicial.',
  `numero_operacion` VARCHAR(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin NOT NULL COMMENT 'Código de operación normalizado como texto, preservando ceros iniciales. No es único por sí solo. Las correcciones operativas conservan la identidad inicial y su historial.',
  `fecha` DATE NOT NULL COMMENT 'Fecha civil bancaria sin hora ni conversión UTC/Lima. Integra la identidad inicial; una corrección no permite que una relectura del origen duplique el registro.',
  `descripcion` VARCHAR(500) NOT NULL COMMENT 'Descripción bancaria vigente, inicialmente copiada de origen o alta manual. No integra la identidad; una diferencia remota genera incidencia sin sobrescribirla silenciosamente.',
  `signo` TINYINT NOT NULL COMMENT 'Dirección respecto de la cuenta del factor: 1=abono o ingreso y -1=cargo o egreso. Cero no está permitido. Determina la dirección de monto y monto_neto; no se almacenan importes operativos negativos.',
  `monto` DECIMAL(20,2) NOT NULL COMMENT 'Magnitud estrictamente positiva en la moneda del movimiento. Efecto firmado=signo por monto. Se usa aritmética decimal exacta, nunca Number para normalizar dinero, y no se persiste otro monto firmado.',
  `origen_alta` VARCHAR(20) CHARACTER SET ascii COLLATE ascii_bin NOT NULL COMMENT 'Procedencia inicial inmutable: MANUAL, SINCRONIZACION o LEGADO. Un alta manual luego observada en MySQL mantiene su UUID, autoría y origen_alta.',
  `identidad_version` SMALLINT UNSIGNED NOT NULL DEFAULT 1 COMMENT 'Versión de normalización y serialización de identidad. V1 usa cuenta local, fecha, operación, signo y monto positivo fijo. Un cambio de algoritmo no reescribe retroactivamente las identidades existentes.',
  `identidad_datos` JSON NOT NULL COMMENT 'Tupla inicial inmutable V1, en orden: ID interno de cuenta como texto, fecha YYYY-MM-DD, operación normalizada, signo como texto 1 o -1 y monto positivo con dos decimales como texto. Excluye descripción, fuente y estado.',
  `identidad_sha256` CHAR(64) CHARACTER SET ascii COLLATE ascii_bin NOT NULL COMMENT 'SHA-256 hexadecimal minúsculo del JSON canónico UTF-8 de la tupla inicial. El servicio lo calcula, compara componentes ante coincidencias y no lo acepta del frontend ni lo recalcula tras una corrección operativa.',
  `_idorigencuenta` INT UNSIGNED NULL COMMENT 'Mapeo vinculado cuando se confirma evidencia MySQL. NULL mientras el alta es solo manual; vincularlo exige verificar identidad, cuenta y moneda sin sobrescribir enriquecimientos.',
  `datos_origen_iniciales` JSON NULL COMMENT 'Copia inmutable de los siete campos recibidos; LEGADO incluye también enriquecimientos históricos. Conserva valores originales, incluidos montos firmados como texto de evidencia, nunca como importes operativos. Excluye secretos.',
  `_idsincronizacion_inicial` INT UNSIGNED NULL COMMENT 'Primera ejecución que confirmó evidencia remota. Se completa si un alta manual aparece luego en MySQL sin cambiar su autoría ni identidad local.',
  `_idsincronizacion_ultima` INT UNSIGNED NULL COMMENT 'Última ejecución que observó de forma compatible la identidad en MySQL. Las diferencias o datos inválidos producen incidencia y no confirman una versión operativa nueva.',
  `ultima_observacion` TIMESTAMP(3) NULL COMMENT 'Instante UTC de última observación compatible. No es fecha de modificación bancaria ni cursor incremental y no prueba que el banco no haya publicado otros movimientos.',
  `tipo_operacion` VARCHAR(500) NULL COMMENT 'Clasificación operativa local compatible inicialmente con tipooperacion remoto. Se preserva en la carga histórica y no se sobrescribe en relecturas; la descripción no aprueba una regla financiera automática.',
  `detalle_fecha` DATE NULL COMMENT 'Fecha civil adicional de comprobante o detalle bancario. NULL es desconocida; no se inventa copiando fecha ni se desplaza mediante UTC/Lima.',
  `detalle_hora` TIME(0) NULL COMMENT 'Hora local del detalle en Lima, no duración ni instante UTC. La carga histórica valida el texto remoto y genera incidencia si no representa una hora entre 00:00:00 y 23:59:59.',
  `origen_cuenta` VARCHAR(500) NULL COMMENT 'Cuenta de la contraparte ordenante según evidencia, como texto con ceros iniciales. Puede ser desconocida y no crea automáticamente cuentas ni relaciones de otros módulos.',
  `origen_nombre` VARCHAR(500) NULL COMMENT 'Nombre del ordenante obtenido de evidencia o completado localmente. Es información sensible, editable con historial y excluida de logs técnicos.',
  `origen_comision` DECIMAL(20,2) NULL COMMENT 'Magnitud no negativa de comisión de origen. NULL es desconocido y 0 es comisión conocida igual a cero. No determina dirección ni modifica automáticamente monto.',
  `destino_cuenta` VARCHAR(500) NULL COMMENT 'Cuenta de contraparte beneficiaria según evidencia. Se conserva como texto; no sustituye la cuenta del factor ni crea una asociación con pagos o factoring.',
  `destino_nombre` VARCHAR(500) NULL COMMENT 'Nombre del beneficiario registrado desde evidencia o completado localmente. Su cambio se audita y no se utiliza como identidad del movimiento.',
  `destino_comision` DECIMAL(20,2) NULL COMMENT 'Magnitud no negativa de comisión de destino cuando se conoce. NULL y 0 son distintos; no se aplica una fórmula automática de neto a partir de este campo.',
  `monto_neto` DECIMAL(20,2) NULL COMMENT 'Magnitud no negativa del neto, cuya dirección la determina signo. El legado firmado se transforma solo tras validar coherencia de dirección; NULL es desconocido y no se deduce una fórmula universal de comisiones.',
  `referencia_descripcion` VARCHAR(500) NULL COMMENT 'Explicación operativa local preservada del legado. Se modifica con historial y nunca se sobrescribe mediante sincronización recurrente.',
  `referencia_proveedor_ruc` VARCHAR(50) NULL COMMENT 'Referencia textual histórica al RUC del proveedor. No es FK ni implica una relación validada con empresas del proyecto.',
  `referencia_proveedor_factura` VARCHAR(50) NULL COMMENT 'Referencia textual histórica a factura del proveedor. No crea comprobantes, vínculos ni aplicaciones monetarias dentro de esta etapa.',
  `referencia_proveedor_boleta` VARCHAR(50) NULL COMMENT 'Referencia textual histórica a boleta de proveedor. NULL indica ausencia; no se convierte en factura ni en asociación automática.',
  `referencia_ft_factura` VARCHAR(50) NULL COMMENT 'Referencia textual histórica a comprobante del factor. Se preserva para trazabilidad, sin FK ni creación de relaciones con comprobantes.',
  `referencia_ft_op_factoring` VARCHAR(200) NULL COMMENT 'Referencia textual histórica que puede mencionar varias operaciones. Se conserva íntegra, sin interpretarla, repartir importes ni vincularla con factoring o pagos en esta etapa.',
  `motivo_anulacion` VARCHAR(500) NULL COMMENT 'Justificación obligatoria cuando estado=2. La anulación conserva identidad e historial para que una relectura no recree el movimiento; no anula registros de otros módulos.',
  `version` INT UNSIGNED NOT NULL DEFAULT 1 COMMENT 'Versión incremental para edición optimista. Enriquecer, corregir o anular exige la versión vigente y anexar el evento en la misma transacción del cambio.',
  `idusuariocrea` INT NOT NULL COMMENT 'Usuario autenticado o cuenta técnica habilitada responsable del alta. Se asigna explícitamente en el servicio; no se acepta del frontend ni se atribuye automáticamente al usuario 1.',
  `fechacrea` TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3) COMMENT 'Instante de creación con milisegundos y sesión de base de datos en UTC. No representa la fecha civil bancaria ni debe desplazarla al visualizar el movimiento en Lima.',
  `idusuariomod` INT NOT NULL COMMENT 'Usuario de la última modificación autorizada, obtenido de la sesión o cuenta técnica por el servicio. Se actualiza junto con el cambio y su evento histórico.',
  `fechamod` TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3) COMMENT 'Instante UTC de última modificación, actualizado explícitamente por el servicio. No tiene ON UPDATE ni se utiliza como cursor de modificaciones del MySQL remoto.',
  `estado` TINYINT NOT NULL DEFAULT 1 COMMENT 'Vigencia lógica del proyecto: 1=ACTIVO y 2=ELIMINADO. No implica borrado físico, ausencia del origen, éxito de sincronización ni conciliación con pagos.',
  PRIMARY KEY (`_idfactortransaccionbancaria`),
  UNIQUE KEY `UQ_ftb_uuid` (`factortransaccionbancariaid`),
  UNIQUE KEY `UQ_ftb_code` (`code`),
  UNIQUE KEY `UQ_ftb_identidad` (`identidad_sha256`),
  KEY `IX_ftb_cuenta_fecha` (`_idfactorcuentabancaria`, `fecha`),
  KEY `IX_ftb_origen` (`_idorigencuenta`),
  KEY `IX_ftb_sync_inicial` (`_idsincronizacion_inicial`),
  KEY `IX_ftb_sync_ultima` (`_idsincronizacion_ultima`),
  CONSTRAINT `FK_ftb_factorcuenta` FOREIGN KEY (`_idfactorcuentabancaria`) REFERENCES `factor_cuenta_bancaria` (`_idfactorcuentabancaria`) ON DELETE RESTRICT ON UPDATE RESTRICT,
  CONSTRAINT `FK_ftb_origen` FOREIGN KEY (`_idorigencuenta`) REFERENCES `factor_transaccion_bancaria_origen_cuenta` (`_idfactortransaccionbancariaorigencuenta`) ON DELETE RESTRICT ON UPDATE RESTRICT,
  CONSTRAINT `FK_ftb_sync_inicial` FOREIGN KEY (`_idsincronizacion_inicial`) REFERENCES `factor_transaccion_bancaria_sincronizacion` (`_idfactortransaccionbancariasincronizacion`) ON DELETE RESTRICT ON UPDATE RESTRICT,
  CONSTRAINT `FK_ftb_sync_ultima` FOREIGN KEY (`_idsincronizacion_ultima`) REFERENCES `factor_transaccion_bancaria_sincronizacion` (`_idfactortransaccionbancariasincronizacion`) ON DELETE RESTRICT ON UPDATE RESTRICT,
  CONSTRAINT `CK_ftb_signo` CHECK (`signo` IN (-1, 1)),
  CONSTRAINT `CK_ftb_monto` CHECK (`monto` > 0),
  CONSTRAINT `CK_ftb_comisiones` CHECK ((`origen_comision` IS NULL OR `origen_comision` >= 0) AND (`destino_comision` IS NULL OR `destino_comision` >= 0)),
  CONSTRAINT `CK_ftb_neto` CHECK (`monto_neto` IS NULL OR `monto_neto` >= 0),
  CONSTRAINT `CK_ftb_hora` CHECK (`detalle_hora` IS NULL OR (`detalle_hora` >= '00:00:00' AND `detalle_hora` <= '23:59:59')),
  CONSTRAINT `CK_ftb_origen_alta` CHECK (`origen_alta` IN ('MANUAL', 'SINCRONIZACION', 'LEGADO')),
  CONSTRAINT `CK_ftb_identidad` CHECK (`identidad_version` = 1 AND JSON_TYPE(`identidad_datos`) = 'ARRAY' AND JSON_LENGTH(`identidad_datos`) = 5 AND `identidad_sha256` REGEXP '^[0-9a-f]{64}$'),
  CONSTRAINT `CK_ftb_operacion` CHECK (CHAR_LENGTH(TRIM(`numero_operacion`)) > 0),
  CONSTRAINT `CK_ftb_evidencia` CHECK ((`_idorigencuenta` IS NULL AND `datos_origen_iniciales` IS NULL AND `_idsincronizacion_inicial` IS NULL AND `_idsincronizacion_ultima` IS NULL AND `ultima_observacion` IS NULL) OR (`_idorigencuenta` IS NOT NULL AND `datos_origen_iniciales` IS NOT NULL AND `_idsincronizacion_inicial` IS NOT NULL AND `_idsincronizacion_ultima` IS NOT NULL AND `ultima_observacion` IS NOT NULL)),
  CONSTRAINT `CK_ftb_importada` CHECK (`origen_alta` = 'MANUAL' OR `_idorigencuenta` IS NOT NULL),
  CONSTRAINT `CK_ftb_snapshot` CHECK (`datos_origen_iniciales` IS NULL OR JSON_TYPE(`datos_origen_iniciales`) = 'OBJECT'),
  CONSTRAINT `CK_ftb_anulacion` CHECK ((`estado` = 1 AND `motivo_anulacion` IS NULL) OR (`estado` = 2 AND `motivo_anulacion` IS NOT NULL AND CHAR_LENGTH(TRIM(`motivo_anulacion`)) > 0)),
  CONSTRAINT `CK_ftb_version` CHECK (`version` > 0),
  CONSTRAINT `CK_ftb_estado` CHECK (`estado` IN (1, 2))
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci ROW_FORMAT=DYNAMIC COMMENT='Movimiento bancario observado o manual en una cuenta real del factor. Monto estrictamente positivo, signo 1=abono y -1=cargo. Conserva identidad inicial, evidencia remota y enriquecimiento local. No registra pagos, no concilia factoring ni modifica saldos de otros módulos.';

CREATE TABLE `factor_transaccion_bancaria_incidencia` (
  `_idfactortransaccionbancariaincidencia` INT UNSIGNED NOT NULL AUTO_INCREMENT COMMENT 'PK interna autoincremental. Identifica este registro para relaciones internas; no se acepta desde la interfaz ni representa el identificador de una operación bancaria.',
  `factortransaccionbancariaincidenciaid` VARCHAR(50) NOT NULL DEFAULT (uuid()) COMMENT 'UUID público único y estable según el estándar del proyecto. Se utiliza en API y permanece tras correcciones, cambios de presentación y eliminación lógica.',
  `code` VARCHAR(20) NOT NULL COMMENT 'Código único de presentación generado por el servicio según el estándar del proyecto. No sustituye al UUID ni al número de operación del banco.',
  `_idconexion` INT UNSIGNED NULL COMMENT 'Conexión implicada en un conflicto remoto. NULL para incidencias puramente manuales; el servicio valida coincidencia con las ejecuciones relacionadas.',
  `_idsincronizacion_inicial` INT UNSIGNED NULL COMMENT 'Ejecución en la que apareció el conflicto. Al repetirse, se conserva esta referencia y se actualizan última ejecución y contador.',
  `_idsincronizacion_ultima` INT UNSIGNED NULL COMMENT 'Última ejecución que observó el mismo conflicto. Debe pertenecer a la misma conexión; no se inserta indefinidamente una alerta idéntica por cada relectura.',
  `_idfactortransaccionbancaria` INT UNSIGNED NULL COMMENT 'Movimiento local implicado, si existe. NULL cuando una fila no pudo convertirse en movimiento válido; no se crea una transacción ficticia para completar la relación.',
  `tipo` VARCHAR(50) CHARACTER SET ascii COLLATE ascii_bin NOT NULL COMMENT 'Código estable validado por servicio: por ejemplo CUENTA_SIN_MAPEO, SIGNO_INCONSISTENTE, MONEDA_INCONSISTENTE, IDENTIDAD_AMBIGUA o DATOS_ORIGEN_DISTINTOS. No depende del mensaje del driver.',
  `huella` CHAR(64) CHARACTER SET ascii COLLATE ascii_bin NOT NULL COMMENT 'SHA-256 canónico del alcance, tipo y evidencia relevante para agrupar repeticiones. No es la identidad del movimiento; un conflicto con contenido distinto puede producir otra incidencia.',
  `datos_revision` JSON NOT NULL COMMENT 'Evidencia mínima estructurada para revisión financiera, con campos fuente afectados y referencias locales. Excluye contraseñas, nonce, tag, clave y URL de conexión; su acceso es restringido.',
  `situacion` VARCHAR(20) CHARACTER SET ascii COLLATE ascii_bin NOT NULL DEFAULT 'PENDIENTE' COMMENT 'PENDIENTE, RESUELTA o DESCARTADA. Resolver o descartar exige motivo; la repetición posterior reabre con historial. Descartar no convierte una fila inválida en válida.',
  `veces_observada` INT UNSIGNED NOT NULL DEFAULT 1 COMMENT 'Repeticiones de esta huella, incrementadas con control de concurrencia. No representa cantidad de movimientos bancarios reales.',
  `ultima_observacion` TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3) COMMENT 'Última observación UTC del conflicto. La primera se conserva en fechacrea; estas fechas describen el proceso local, no la fecha bancaria.',
  `resolucion_motivo` VARCHAR(500) NULL COMMENT 'Justificación obligatoria al resolver o descartar, con evidencia y acción tomada. No sustituye el evento histórico ni autoriza escritura en MySQL remoto.',
  `idusuarioresuelve` INT NULL COMMENT 'Usuario autenticado de la resolución o descarte. Lo establece el servicio junto con fecha y motivo; no se acepta libremente del payload.',
  `resolucion_fecha` TIMESTAMP(3) NULL COMMENT 'Instante UTC de resolución o descarte. NULL mientras pendiente; al reabrir se conserva la resolución anterior en historial antes de limpiar estos campos.',
  `version` INT UNSIGNED NOT NULL DEFAULT 1 COMMENT 'Versión incremental para evitar que dos revisores pierdan o sobrescriban decisiones concurrentes sobre la misma incidencia.',
  `idusuariocrea` INT NOT NULL COMMENT 'Usuario autenticado o cuenta técnica habilitada responsable del alta. Se asigna explícitamente en el servicio; no se acepta del frontend ni se atribuye automáticamente al usuario 1.',
  `fechacrea` TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3) COMMENT 'Instante de creación con milisegundos y sesión de base de datos en UTC. No representa la fecha civil bancaria ni debe desplazarla al visualizar el movimiento en Lima.',
  `idusuariomod` INT NOT NULL COMMENT 'Usuario de la última modificación autorizada, obtenido de la sesión o cuenta técnica por el servicio. Se actualiza junto con el cambio y su evento histórico.',
  `fechamod` TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3) COMMENT 'Instante UTC de última modificación, actualizado explícitamente por el servicio. No tiene ON UPDATE ni se utiliza como cursor de modificaciones del MySQL remoto.',
  `estado` TINYINT NOT NULL DEFAULT 1 COMMENT 'Vigencia lógica del proyecto: 1=ACTIVO y 2=ELIMINADO. No implica borrado físico, ausencia del origen, éxito de sincronización ni conciliación con pagos.',
  PRIMARY KEY (`_idfactortransaccionbancariaincidencia`),
  UNIQUE KEY `UQ_ftbi_uuid` (`factortransaccionbancariaincidenciaid`),
  UNIQUE KEY `UQ_ftbi_code` (`code`),
  UNIQUE KEY `UQ_ftbi_huella` (`huella`),
  KEY `IX_ftbi_revision` (`situacion`, `ultima_observacion`),
  KEY `IX_ftbi_conexion` (`_idconexion`),
  KEY `IX_ftbi_sync_inicial` (`_idsincronizacion_inicial`),
  KEY `IX_ftbi_sync_ultima` (`_idsincronizacion_ultima`),
  KEY `IX_ftbi_movimiento` (`_idfactortransaccionbancaria`),
  CONSTRAINT `FK_ftbi_conexion` FOREIGN KEY (`_idconexion`) REFERENCES `configuracion_bbdd` (`_idconfiguracionbbdd`) ON DELETE RESTRICT ON UPDATE RESTRICT,
  CONSTRAINT `FK_ftbi_sync_inicial` FOREIGN KEY (`_idsincronizacion_inicial`) REFERENCES `factor_transaccion_bancaria_sincronizacion` (`_idfactortransaccionbancariasincronizacion`) ON DELETE RESTRICT ON UPDATE RESTRICT,
  CONSTRAINT `FK_ftbi_sync_ultima` FOREIGN KEY (`_idsincronizacion_ultima`) REFERENCES `factor_transaccion_bancaria_sincronizacion` (`_idfactortransaccionbancariasincronizacion`) ON DELETE RESTRICT ON UPDATE RESTRICT,
  CONSTRAINT `FK_ftbi_movimiento` FOREIGN KEY (`_idfactortransaccionbancaria`) REFERENCES `factor_transaccion_bancaria` (`_idfactortransaccionbancaria`) ON DELETE RESTRICT ON UPDATE RESTRICT,
  CONSTRAINT `CK_ftbi_huella` CHECK (`huella` REGEXP '^[0-9a-f]{64}$'),
  CONSTRAINT `CK_ftbi_situacion` CHECK (`situacion` IN ('PENDIENTE', 'RESUELTA', 'DESCARTADA')),
  CONSTRAINT `CK_ftbi_resolucion` CHECK ((`situacion` = 'PENDIENTE' AND `resolucion_motivo` IS NULL AND `idusuarioresuelve` IS NULL AND `resolucion_fecha` IS NULL) OR (`situacion` <> 'PENDIENTE' AND `resolucion_motivo` IS NOT NULL AND CHAR_LENGTH(TRIM(`resolucion_motivo`)) > 0 AND `idusuarioresuelve` IS NOT NULL AND `resolucion_fecha` IS NOT NULL)),
  CONSTRAINT `CK_ftbi_sync` CHECK ((`_idsincronizacion_inicial` IS NULL AND `_idsincronizacion_ultima` IS NULL) OR (`_idsincronizacion_inicial` IS NOT NULL AND `_idsincronizacion_ultima` IS NOT NULL AND `_idconexion` IS NOT NULL)),
  CONSTRAINT `CK_ftbi_contadores` CHECK (`veces_observada` > 0 AND `version` > 0),
  CONSTRAINT `CK_ftbi_estado` CHECK (`estado` IN (1, 2))
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci ROW_FORMAT=DYNAMIC COMMENT='Conflicto de importación o revisión manual: cuenta desconocida, moneda o signo incompatible, duplicado ambiguo o diferencia del origen. La resolución es explícita y auditada; no confirma pagos, no corrige MySQL ni oculta diferencias financieras.';

CREATE TABLE `factor_transaccion_bancaria_historial` (
  `_idfactortransaccionbancariahistorial` INT UNSIGNED NOT NULL AUTO_INCREMENT COMMENT 'PK interna autoincremental. Identifica este registro para relaciones internas; no se acepta desde la interfaz ni representa el identificador de una operación bancaria.',
  `factortransaccionbancariahistorialid` VARCHAR(50) NOT NULL DEFAULT (uuid()) COMMENT 'UUID público único y estable según el estándar del proyecto. Se utiliza en API y permanece tras correcciones, cambios de presentación y eliminación lógica.',
  `code` VARCHAR(20) NOT NULL COMMENT 'Código único de presentación generado por el servicio según el estándar del proyecto. No sustituye al UUID ni al número de operación del banco.',
  `_idfactortransaccionbancaria` INT UNSIGNED NULL COMMENT 'Movimiento afectado por alta, enriquecimiento, corrección, anulación o vinculación. Exactamente una de las cuatro referencias de entidad del evento debe estar definida.',
  `_idconexion` INT UNSIGNED NULL COMMENT 'Conexión afectada por configuración o rotación de secreto. Registra que cambió la contraseña, sin valor, ciphertext, nonce, tag ni clave externa.',
  `_idorigencuenta` INT UNSIGNED NULL COMMENT 'Mapeo afectado por alta, habilitación o suspensión. No habilita reasignar silenciosamente movimientos históricos a otra cuenta.',
  `_idincidencia` INT UNSIGNED NULL COMMENT 'Incidencia resuelta, descartada o reabierta. Se conserva motivo y evidencia con acceso restringido; la acción no equivale a registrar pagos.',
  `evento` VARCHAR(50) CHARACTER SET ascii COLLATE ascii_bin NOT NULL COMMENT 'Código estable validado por servicio, como ALTA, ENRIQUECIMIENTO, CORRECCION, ANULACION, VINCULO_ORIGEN, ROTACION_SECRETO, RESOLUCION o REAPERTURA. Su etiqueta no determina permisos.',
  `motivo` VARCHAR(500) NOT NULL COMMENT 'Justificación del cambio o descripción del alta, obligatoria y registrada con el actor. Excluye secretos, cadenas de conexión y mensajes del driver sin sanitizar.',
  `datos_antes` JSON NULL COMMENT 'Valores previos de campos afectados según lista permitida por entidad; NULL en altas. En conexión excluye contraseña y materiales criptográficos; en movimiento protege datos de contrapartes.',
  `datos_despues` JSON NULL COMMENT 'Valores posteriores permitidos o resumen de acción sin secretos. Se anexa en la misma transacción del cambio; una rotación registra solo metadatos autorizados que no reconstruyen la contraseña.',
  `idusuariocrea` INT NOT NULL COMMENT 'Usuario autenticado o cuenta técnica habilitada responsable del alta. Se asigna explícitamente en el servicio; no se acepta del frontend ni se atribuye automáticamente al usuario 1.',
  `fechacrea` TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3) COMMENT 'Instante de creación con milisegundos y sesión de base de datos en UTC. No representa la fecha civil bancaria ni debe desplazarla al visualizar el movimiento en Lima.',
  `idusuariomod` INT NOT NULL COMMENT 'Usuario de creación conservado por convención. El historial es de solo anexado: las rectificaciones generan otro evento y no modifican este registro.',
  `fechamod` TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3) COMMENT 'Instante de creación conservado por convención. Este evento no se edita desde el módulo; una rectificación posterior se anexa como otro evento.',
  `estado` TINYINT NOT NULL DEFAULT 1 COMMENT 'Vigencia técnica fija en 1=ACTIVO. El CRUD no elimina lógica ni físicamente eventos históricos; el campo conserva la convención del proyecto.',
  PRIMARY KEY (`_idfactortransaccionbancariahistorial`),
  UNIQUE KEY `UQ_ftbh_uuid` (`factortransaccionbancariahistorialid`),
  UNIQUE KEY `UQ_ftbh_code` (`code`),
  KEY `IX_ftbh_movimiento_fecha` (`_idfactortransaccionbancaria`, `fechacrea`),
  KEY `IX_ftbh_conexion_fecha` (`_idconexion`, `fechacrea`),
  KEY `IX_ftbh_mapeo_fecha` (`_idorigencuenta`, `fechacrea`),
  KEY `IX_ftbh_incidencia_fecha` (`_idincidencia`, `fechacrea`),
  CONSTRAINT `FK_ftbh_movimiento` FOREIGN KEY (`_idfactortransaccionbancaria`) REFERENCES `factor_transaccion_bancaria` (`_idfactortransaccionbancaria`) ON DELETE RESTRICT ON UPDATE RESTRICT,
  CONSTRAINT `FK_ftbh_conexion` FOREIGN KEY (`_idconexion`) REFERENCES `configuracion_bbdd` (`_idconfiguracionbbdd`) ON DELETE RESTRICT ON UPDATE RESTRICT,
  CONSTRAINT `FK_ftbh_origen` FOREIGN KEY (`_idorigencuenta`) REFERENCES `factor_transaccion_bancaria_origen_cuenta` (`_idfactortransaccionbancariaorigencuenta`) ON DELETE RESTRICT ON UPDATE RESTRICT,
  CONSTRAINT `FK_ftbh_incidencia` FOREIGN KEY (`_idincidencia`) REFERENCES `factor_transaccion_bancaria_incidencia` (`_idfactortransaccionbancariaincidencia`) ON DELETE RESTRICT ON UPDATE RESTRICT,
  CONSTRAINT `CK_ftbh_entidad` CHECK ((`_idfactortransaccionbancaria` IS NOT NULL) + (`_idconexion` IS NOT NULL) + (`_idorigencuenta` IS NOT NULL) + (`_idincidencia` IS NOT NULL) = 1),
  CONSTRAINT `CK_ftbh_motivo` CHECK (CHAR_LENGTH(TRIM(`motivo`)) > 0),
  CONSTRAINT `CK_ftbh_estado` CHECK (`estado` = 1)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci ROW_FORMAT=DYNAMIC COMMENT='Historial de solo anexado de movimientos, conexión MySQL, mapeos e incidencias. Cada evento referencia exactamente una entidad y conserva actor, motivo y cambios autorizados. No contiene secretos ni material criptográfico y no se borra desde el CRUD.';
